from ta_emss.utilities.trs.jsonrpc import JsonRpcLayer

rpc_clients_registry = {}


def register_rpc_layer(rpcL, rpc_connection_name):
    '''
    Register rpc
    '''
    global rpc_clients_registry
    assert isinstance(rpcL, JsonRpcLayer)
    rpc_clients_registry[rpc_connection_name] = rpcL


def rpc_client(rpc_connection_name):
    '''
    Return registered rpc
    '''
    global rpc_clients_registry
    if rpc_connection_name in rpc_clients_registry:
        return rpc_clients_registry[rpc_connection_name]
    return None
